/* CSS PART 1 OF 4 */

/* =========================================
   DESIGN SYSTEM
   Josh Brooks Construction & Renovation Inc.
   Original visual direction: Modern Craft
   ========================================= */

:root {
  /* Core palette */
  --color-ink: #202a30;
  --color-ink-soft: #34434a;
  --color-slate: #56666b;
  --color-muted: #778387;

  --color-paper: #f7f6f2;
  --color-white: #ffffff;
  --color-stone: #eae8e0;
  --color-stone-dark: #d9d6cc;

  --color-accent: #c87943;
  --color-accent-dark: #a95e30;
  --color-accent-light: #e6b58d;

  --color-success: #52705d;
  --color-border: rgba(32, 42, 48, 0.13);

  /* Typography */
  --font-heading: "Arial", "Helvetica Neue", sans-serif;
  --font-body: "Helvetica Neue", Arial, sans-serif;

  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.375rem;
  --font-size-2xl: clamp(1.75rem, 3vw, 2.5rem);
  --font-size-3xl: clamp(2.25rem, 4.5vw, 3.75rem);
  --font-size-hero: clamp(2.8rem, 6.5vw, 5.75rem);

  --line-height-tight: 1.08;
  --line-height-heading: 1.2;
  --line-height-body: 1.7;

  --letter-spacing-tight: -0.045em;
  --letter-spacing-normal: -0.015em;
  --letter-spacing-wide: 0.12em;

  /* Layout */
  --container-width: 1240px;
  --container-narrow: 860px;
  --page-gutter: clamp(1.25rem, 5vw, 5rem);

  --header-height: 88px;
  --section-spacing: clamp(4.5rem, 9vw, 8rem);
  --section-spacing-small: clamp(3rem, 6vw, 5rem);

  /* Spacing scale */
  --space-1: 0.375rem;
  --space-2: 0.625rem;
  --space-3: 0.875rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;
  --space-8: 4rem;
  --space-9: 5rem;
  --space-10: 6rem;

  /* Borders and elevation */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 14px;
  --radius-pill: 999px;

  --shadow-soft: 0 8px 30px rgba(32, 42, 48, 0.07);
  --shadow-card: 0 18px 50px rgba(32, 42, 48, 0.11);

  /* Motion */
  --transition-fast: 160ms ease;
  --transition-normal: 260ms ease;
  --transition-slow: 450ms ease;

  /* Layering */
  --z-base: 1;
  --z-header: 100;
  --z-overlay: 200;
  --z-modal: 300;
}


/* =========================================
   RESET AND DOCUMENT FOUNDATIONS
   ========================================= */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-height) + 24px);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-width: 320px;
  margin: 0;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  line-height: var(--line-height-body);
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
input,
select,
textarea {
  color: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  margin: 0;
  padding: 0;
}

li {
  list-style: none;
}

p,
h1,
h2,
h3,
h4,
h5,
h6 {
  margin-top: 0;
}

p:last-child {
  margin-bottom: 0;
}

fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

::selection {
  background: var(--color-accent);
  color: var(--color-white);
}


/* =========================================
   ACCESSIBILITY FOUNDATIONS
   ========================================= */

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: var(--z-modal);
  top: 12px;
  left: 12px;
  padding: 12px 20px;
  transform: translateY(-150%);
  border-radius: var(--radius-sm);
  background: var(--color-ink);
  color: var(--color-white);
  font-weight: 700;
  transition: transform var(--transition-fast);
}

.skip-link:focus {
  transform: translateY(0);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* =========================================
   TYPOGRAPHY SYSTEM
   ========================================= */

h1,
h2,
h3,
h4,
h5,
h6 {
  margin-bottom: var(--space-5);
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-weight: 750;
  letter-spacing: var(--letter-spacing-tight);
  line-height: var(--line-height-heading);
}

h1 {
  font-size: var(--font-size-hero);
  line-height: var(--line-height-tight);
  letter-spacing: -0.055em;
}

h2 {
  font-size: var(--font-size-3xl);
}

h3 {
  font-size: var(--font-size-2xl);
}

h4 {
  font-size: var(--font-size-xl);
}

h5 {
  font-size: var(--font-size-lg);
}

h6 {
  font-size: var(--font-size-base);
}

p {
  margin-bottom: var(--space-5);
  color: var(--color-slate);
}

strong,
b {
  color: var(--color-ink);
  font-weight: 700;
}

small {
  font-size: var(--font-size-sm);
}

.text-large {
  font-size: clamp(1.1rem, 2vw, 1.3rem);
  line-height: 1.75;
}

.text-small {
  font-size: var(--font-size-sm);
}

.text-muted {
  color: var(--color-muted);
}

.text-accent {
  color: var(--color-accent-dark);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: var(--space-5);
  color: var(--color-accent-dark);
  font-size: var(--font-size-xs);
  font-weight: 800;
  letter-spacing: var(--letter-spacing-wide);
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 2px;
  background: var(--color-accent);
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: var(--space-7);
}

.section-heading h2 {
  margin-bottom: var(--space-4);
}

.section-heading p {
  max-width: 650px;
  font-size: var(--font-size-lg);
}


/* =========================================
   PAGE GRID AND CONTAINERS
   ========================================= */

.container {
  width: min(
    var(--container-width),
    calc(100% - (var(--page-gutter) * 2))
  );
  margin-inline: auto;
}

.container--narrow {
  width: min(
    var(--container-narrow),
    calc(100% - (var(--page-gutter) * 2))
  );
  margin-inline: auto;
}

.container--full {
  width: calc(100% - (var(--page-gutter) * 2));
  margin-inline: auto;
}

.site-wrapper {
  width: 100%;
  min-height: 100vh;
  overflow: clip;
}

.section {
  position: relative;
  padding-block: var(--section-spacing);
}

.section--compact {
  padding-block: var(--section-spacing-small);
}

.section--light {
  background: var(--color-paper);
}

.section--white {
  background: var(--color-white);
}

.section--stone {
  background: var(--color-stone);
}

.section--dark {
  background: var(--color-ink);
  color: var(--color-white);
}

.section--dark h2,
.section--dark h3,
.section--dark h4,
.section--dark strong {
  color: var(--color-white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.73);
}


/* =========================================
   REUSABLE GRID FOUNDATIONS
   ========================================= */

.grid {
  display: grid;
  gap: var(--space-6);
}

.grid--2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid--3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid--4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.grid--split {
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(2rem, 6vw, 6rem);
}

.flex {
  display: flex;
}

.flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.flex-column {
  display: flex;
  flex-direction: column;
}

.align-center {
  align-items: center;
}

.justify-center {
  justify-content: center;
}

.gap-sm {
  gap: var(--space-3);
}

.gap-md {
  gap: var(--space-5);
}

.gap-lg {
  gap: var(--space-7);
}


/* =========================================
   IMAGE AND MEDIA FOUNDATIONS
   ========================================= */

.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--color-stone);
  border-radius: var(--radius-md);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-cover {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-landscape {
  aspect-ratio: 16 / 10;
}

.image-portrait {
  aspect-ratio: 4 / 5;
}

.image-square {
  aspect-ratio: 1;
}


/* =========================================
   RESPONSIVE FOUNDATIONS
   ========================================= */

@media (max-width: 1024px) {
  :root {
    --header-height: 76px;
    --section-spacing: 5.5rem;
  }

  .grid--4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid--3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid--split {
    gap: var(--space-7);
  }
}

@media (max-width: 700px) {
  :root {
    --page-gutter: 1.25rem;
    --header-height: 70px;
    --section-spacing: 4.5rem;
    --section-spacing-small: 3rem;
  }

  h1 {
    font-size: clamp(2.65rem, 11vw, 4rem);
  }

  h2 {
    font-size: clamp(2rem, 8vw, 2.8rem);
  }

  h3 {
    font-size: 1.65rem;
  }

  .grid--2,
  .grid--3,
  .grid--4,
  .grid--split {
    grid-template-columns: 1fr;
  }

  .grid {
    gap: var(--space-5);
  }

  .section-heading {
    margin-bottom: var(--space-6);
  }

  .flex-between {
    align-items: flex-start;
  }

  .container--full {
    width: calc(100% - (var(--page-gutter) * 2));
  }
}

@media (max-width: 420px) {
  :root {
    --page-gutter: 1rem;
  }

  .eyebrow {
    font-size: 0.68rem;
    letter-spacing: 0.1em;
  }
}
