/* CSS PART 2 OF 4 */

/* =========================================
   SITE HEADER
   ========================================= */

.site-header {
  position: sticky;
  z-index: var(--z-header);
  top: 0;
  width: 100%;
  min-height: var(--header-height);
  background: rgba(247, 246, 242, 0.97);
  border-bottom: 1px solid var(--color-border);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.header-inner {
  display: flex;
  width: min(
    var(--container-width),
    calc(100% - (var(--page-gutter) * 2))
  );
  min-height: var(--header-height);
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  margin-inline: auto;
}

.site-brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 13px;
  color: var(--color-ink);
}

.site-brand img {
  width: 56px;
  height: 56px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1.15;
}

.brand-name {
  max-width: 190px;
  font-size: 0.88rem;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.brand-description {
  color: var(--color-muted);
  font-size: 0.63rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}


/* =========================================
   PRIMARY NAVIGATION
   ========================================= */

.primary-navigation {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 2vw, 2rem);
}

.primary-navigation > a,
.nav-dropdown-trigger {
  position: relative;
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  padding: 8px 0;
  border: 0;
  background: transparent;
  color: var(--color-ink-soft);
  font-size: 0.82rem;
  font-weight: 700;
  white-space: nowrap;
  transition: color var(--transition-fast);
}

.primary-navigation > a::after,
.nav-dropdown-trigger::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--color-accent);
  content: "";
  transition: transform var(--transition-normal);
}

.primary-navigation > a:hover,
.nav-dropdown-trigger:hover {
  color: var(--color-accent-dark);
}

.primary-navigation > a:hover::after,
.primary-navigation > a:focus-visible::after,
.nav-dropdown-trigger:hover::after {
  transform: scaleX(1);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-trigger {
  gap: 7px;
  cursor: pointer;
}

.nav-dropdown-trigger::before {
  width: 7px;
  height: 7px;
  transform: rotate(45deg) translateY(-2px);
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  content: "";
  order: 2;
}

.nav-dropdown-menu {
  position: absolute;
  z-index: var(--z-overlay);
  top: calc(100% + 8px);
  left: -18px;
  display: none;
  width: 230px;
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-white);
  box-shadow: var(--shadow-card);
}

.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown:focus-within .nav-dropdown-menu,
.nav-dropdown[aria-expanded="true"] .nav-dropdown-menu {
  display: grid;
  gap: 3px;
}

.nav-dropdown-menu a {
  display: block;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  color: var(--color-ink-soft);
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition:
    color var(--transition-fast),
    background var(--transition-fast);
}

.nav-dropdown-menu a:hover,
.nav-dropdown-menu a:focus-visible {
  background: var(--color-paper);
  color: var(--color-accent-dark);
}


/* =========================================
   HEADER CONVERSION ACTION
   ========================================= */

.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 13px 24px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--color-accent);
  color: var(--color-white);
  font-size: 0.9rem;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast),
    transform var(--transition-fast),
    box-shadow var(--transition-fast);
}

.button:hover {
  transform: translateY(-2px);
  background: var(--color-accent-dark);
  box-shadow: 0 8px 20px rgba(169, 94, 48, 0.2);
}

.button:active {
  transform: translateY(0);
}

.button--header {
  min-height: 44px;
  padding: 11px 18px;
  font-size: 0.8rem;
  white-space: nowrap;
}

.button--dark {
  background: var(--color-ink);
}

.button--dark:hover {
  background: var(--color-ink-soft);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--color-white);
}

.button--outline:hover {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-ink);
}

.button--light {
  border-color: var(--color-border);
  background: var(--color-white);
  color: var(--color-ink);
}

.button--light:hover {
  border-color: var(--color-accent);
  background: var(--color-paper);
}

.button-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}


/* =========================================
   MOBILE NAVIGATION CONTROLS
   ========================================= */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-white);
  color: var(--color-ink);
  cursor: pointer;
}

.menu-toggle span {
  display: block;
  width: 20px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transition:
    transform var(--transition-fast),
    opacity var(--transition-fast);
}

.menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(8px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-8px) rotate(-45deg);
}


/* =========================================
   HERO SECTION
   ========================================= */

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - var(--header-height)));
  align-items: center;
  overflow: hidden;
  background: var(--color-ink);
  color: var(--color-white);
}

.hero::before {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(20, 29, 34, 0.96) 0%,
      rgba(20, 29, 34, 0.86) 38%,
      rgba(20, 29, 34, 0.38) 72%,
      rgba(20, 29, 34, 0.15) 100%
    );
  content: "";
  z-index: 1;
}

.hero-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero-inner {
  position: relative;
  z-index: 2;
  width: min(
    var(--container-width),
    calc(100% - (var(--page-gutter) * 2))
  );
  margin-inline: auto;
  padding-block: clamp(5rem, 9vw, 8rem);
}

.hero-content {
  max-width: 760px;
}

.hero .eyebrow {
  color: var(--color-accent-light);
}

.hero .eyebrow::before {
  background: var(--color-accent-light);
}

.hero h1 {
  max-width: 780px;
  margin-bottom: var(--space-5);
  color: var(--color-white);
  font-size: var(--font-size-hero);
  line-height: 1.02;
  letter-spacing: -0.06em;
}

.hero h1 em {
  color: var(--color-accent-light);
  font-style: normal;
}

.hero-description {
  max-width: 610px;
  margin-bottom: var(--space-7);
  color: rgba(255, 255, 255, 0.83);
  font-size: clamp(1.05rem, 2vw, 1.25rem);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero .button {
  min-height: 58px;
  padding-inline: 27px;
}

.hero .button--secondary {
  border-color: rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.08);
  color: var(--color-white);
  backdrop-filter: blur(8px);
}

.hero .button--secondary:hover {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-ink);
}


/* =========================================
   HERO TRUST / CREDENTIAL STRIP
   ========================================= */

.hero-credentials {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 28px;
  margin-top: var(--space-7);
  padding-top: var(--space-5);
  border-top: 1px solid rgba(255, 255, 255, 0.25);
}

.hero-credential {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.hero-credential-mark {
  display: inline-flex;
  width: 25px;
  height: 25px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-accent-light);
  border-radius: 50%;
  color: var(--color-accent-light);
  font-size: 0.7rem;
  font-weight: 800;
}


/* =========================================
   HERO IMAGE CAPTION
   ========================================= */

.hero-caption {
  position: absolute;
  z-index: 2;
  right: var(--page-gutter);
  bottom: 28px;
  max-width: 250px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.7rem;
  line-height: 1.5;
  text-align: right;
