/* =========================================
   RESPONSIVE HEADER AND NAVIGATION
   ========================================= */

@media (max-width: 1100px) {
  .header-inner {
    gap: 1rem;
  }

  .primary-navigation {
    gap: 1rem;
  }

  .primary-navigation > a,
  .nav-dropdown-trigger {
    font-size: 0.76rem;
  }

  .brand-name {
    max-width: 165px;
    font-size: 0.8rem;
  }

  .site-brand img {
    width: 48px;
    height: 48px;
  }
}

@media (max-width: 900px) {
  .menu-toggle {
    display: flex;
  }

  .header-inner {
    position: relative;
  }

  .primary-navigation {
    position: absolute;
    z-index: var(--z-overlay);
    top: calc(100% + 1px);
    right: calc(var(--page-gutter) * -1);
    left: calc(var(--page-gutter) * -1);
    display: none;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    max-height: calc(100svh - var(--header-height));
    padding: 14px var(--page-gutter) 24px;
    overflow-y: auto;
    border-bottom: 1px solid var(--color-border);
    background: var(--color-paper);
    box-shadow: var(--shadow-card);
  }

  .primary-navigation.is-open {
    display: flex;
  }

  .primary-navigation > a,
  .nav-dropdown-trigger {
    width: 100%;
    min-height: 48px;
    justify-content: space-between;
    border-bottom: 1px solid var(--color-border);
    font-size: 0.9rem;
  }

  .primary-navigation > a::after,
  .nav-dropdown-trigger::after {
    display: none;
  }

  .nav-dropdown {
    width: 100%;
  }

  .nav-dropdown-menu {
    position: static;
    width: 100%;
    padding: 5px 0 12px 12px;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  .nav-dropdown-menu a {
    padding: 11px 12px;
  }

  .header-cta {
    display: none;
  }

  .hero {
    min-height: 690px;
  }
}

@media (max-width: 600px) {
  .site-brand {
    gap: 9px;
  }

  .site-brand img {
    width: 43px;
    height: 43px;
  }

  .brand-name {
    max-width: 180px;
    font-size: 0.76rem;
  }

  .brand-description {
    font-size: 0.56rem;
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - var(--header-height)));
    align-items: flex-end;
  }

  .hero::before {
    background: linear-gradient(
      0deg,
      rgba(20, 29, 34, 0.97) 0%,
      rgba(20, 29, 34, 0.86) 48%,
      rgba(20, 29, 34, 0.35) 100%
    );
  }

  .hero-image {
    object-position: 58% center;
  }

  .hero-inner {
    padding-top: 6rem;
    padding-bottom: 4rem;
  }

  .hero h1 {
    font-size: clamp(2.65rem, 12vw, 4.1rem);
  }

  .hero-description {
    font-size: 1rem;
    line-height: 1.65;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-credentials {
    gap: 12px 18px;
    margin-top: var(--space-6);
  }

  .hero-credential {
    font-size: 0.67rem;
  }

  .hero-caption {
    display: none;
  }
}

@media (max-width: 380px) {
  .brand-name {
    max-width: 145px;
    font-size: 0.7rem;
  }

  .hero-credential {
    font-size: 0.61rem;
  }
}
